trial.program_source:
def transform(grid):
 h=len(grid); w=len(grid[0]); pts=[(r,c) for r in range(h) for c in range(w) if grid[r][c]!=0]
 if not pts: return [[0]]
 start=pts[-1]; color=grid[start[0]][start[1]]; seen={start}; stack=[start]
 while stack:
  r,c=stack.pop()
  for dr,dc in [(1,0),(-1,0),(0,1),(0,-1)]:
   p=(r+dr,c+dc)
   if 0<=p[0]<h and 0<=p[1]<w and p not in seen and grid[p[0]][p[1]]==color:
    seen.add(p); stack.append(p)
 a=min(r for r,c in seen); b=max(r for r,c in seen); x=min(c for r,c in seen); y=max(c for r,c in seen)
 return [row[x:y+1] for row in grid[a:b+1]]

